package com.oibsip.onlineexam.ui;
import javax.swing.*;import java.awt.*;import java.util.*;import com.oibsip.onlineexam.model.*;import com.oibsip.onlineexam.util.Constants;
public class ExamPanel extends JPanel {private final MainFrame f;private java.util.List<Question> qs;private int index;private final JLabel counter=new JLabel(),timerLabel=new JLabel();private final JTextArea text=new JTextArea();private final JRadioButton[] opts={new JRadioButton(),new JRadioButton(),new JRadioButton(),new JRadioButton()};private final ButtonGroup group=new ButtonGroup();private final JButton prev=new JButton("Previous"),next=new JButton("Next"),submit=new JButton("Submit Exam");private javax.swing.Timer timer;private long endNanos;public ExamPanel(MainFrame x){f=x;setLayout(new BorderLayout(15,15));JPanel head=new JPanel(new BorderLayout());JLabel title=new JLabel(Constants.EXAM_TITLE);title.setFont(new Font("SansSerif",Font.BOLD,22));head.add(title,BorderLayout.WEST);timerLabel.setFont(new Font("SansSerif",Font.BOLD,18));head.add(timerLabel,BorderLayout.EAST);add(head,BorderLayout.NORTH);JPanel center=new JPanel(new BorderLayout(10,10));text.setEditable(false);text.setLineWrap(true);text.setWrapStyleWord(true);text.setFont(new Font("SansSerif",Font.PLAIN,19));text.setBorder(BorderFactory.createEmptyBorder(15,15,15,15));center.add(text,BorderLayout.NORTH);JPanel choices=new JPanel();choices.setLayout(new BoxLayout(choices,BoxLayout.Y_AXIS));for(JRadioButton o:opts){group.add(o);o.setFont(new Font("SansSerif",Font.PLAIN,17));choices.add(o);choices.add(Box.createVerticalStrut(10));}center.add(choices,BorderLayout.CENTER);add(center,BorderLayout.CENTER);JPanel foot=new JPanel(new BorderLayout());foot.add(counter,BorderLayout.WEST);JPanel b=new JPanel();b.add(prev);b.add(next);b.add(submit);foot.add(b,BorderLayout.EAST);add(foot,BorderLayout.SOUTH);prev.addActionListener(e->{save();if(index>0){index--;render();}});next.addActionListener(e->{save();if(index<qs.size()-1){index++;render();}});submit.addActionListener(e->manualSubmit());}public void begin(){qs=f.questions().findAll();index=0;var s=f.exam().start(qs);f.session().startExam(s);endNanos=System.nanoTime()+Constants.EXAM_DURATION_SECONDS*1_000_000_000L;timer=new javax.swing.Timer(1000,e->tick());timer.setInitialDelay(0);timer.start();render();}private void tick(){long sec=Math.max(0,(endNanos-System.nanoTime())/1_000_000_000L);timerLabel.setText("Time Remaining: "+String.format("%02d:%02d",sec/60,sec%60));if(sec<=0)autoSubmit();}private void render(){Question q=qs.get(index);counter.setText("Question "+(index+1)+" of "+qs.size());text.setText(q.questionText());String[] a={q.optionA(),q.optionB(),q.optionC(),q.optionD()};group.clearSelection();for(int i=0;i<4;i++)opts[i].setText((char)('A'+i)+". "+a[i]);Character saved=f.session().getExam().getAnswers().get(q.id());if(saved!=null)opts[saved-'A'].setSelected(true);prev.setEnabled(index>0);next.setEnabled(index<qs.size()-1);}private void save(){for(int i=0;i<4;i++)if(opts[i].isSelected())f.session().getExam().answer(qs.get(index).id(),(char)('A'+i));}private void manualSubmit(){save();if(JOptionPane.showConfirmDialog(f,"Are you sure you want to submit the examination?","Submit Examination",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)finish(false);}private void autoSubmit(){save();finish(true);}private void finish(boolean auto){if(timer!=null)timer.stop();var s=f.session().getExam();if(s.isSubmitted())return;f.exam().submit(s,auto);if(auto)JOptionPane.showMessageDialog(f,"Time is over. Your examination has been submitted automatically.","Time Expired",JOptionPane.INFORMATION_MESSAGE);f.show(MainFrame.RESULT);}}
